import java.util.Scanner;

public class Main {
    static final int MAXN = 300010;
    static int n, K, mod;
    static int[][] dp = new int[MAXN][20];
    static int[] countArr = new int[MAXN];
    static int[] maxBit = new int[MAXN];
    static long[] comb = new long[MAXN];
    static long[] invComb = new long[MAXN];

    static long fastPower(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long combination(int i, int j) {
        return (comb[i] * invComb[j] % mod) * invComb[i - j] % mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        K = sc.nextInt();
        mod = sc.nextInt();

        if ((n & 1) == 1) {
            System.out.println(fastPower(K, n));
            sc.close();
            return;
        }

        comb[0] = 1;
        for (int i = 1; i <= n; i++) {
            comb[i] = (comb[i - 1] * i) % mod;
        }

        invComb[n] = fastPower(comb[n], mod - 2);
        for (int i = n - 1; i >= 1; i--) {
            invComb[i] = (invComb[i + 1] * (i + 1)) % mod;
        }
        invComb[0] = 1;

        for (int i = 1; i <= n; i++) {
            int count = 0;
            for (int j = 0; j <= 18; j++) {
                if (((1 << j) & i) != 0) {
                    count++;
                }
            }
            countArr[i] = count;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 18; j >= 0; j--) {
                if (((1 << j) & i) != 0) {
                    maxBit[i] = 1 << j;
                    break;
                }
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 20; j++) {
                dp[i][j] = 0;
            }
        }
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            if ((n & i) != i) continue;
            int remaining = i ^ maxBit[i];
            for (int mask = remaining; ; mask = (mask - 1) & remaining) {
                int current = mask + maxBit[i];
                int c2 = i ^ current;
                int limit = Math.min(K - 1, countArr[c2]);
                long tmp = combination(i, current);
                for (int j = 0; j <= limit; j++) {
                    dp[i][j + 1] = (int)((dp[i][j + 1] + (long)dp[c2][j] * tmp) % mod);
                }
                if (mask == 0) break;
            }
        }

        long answer = 0;
        int maxJ = Math.min(countArr[n], K);
        for (int j = 1; j <= maxJ; j++) {
            answer = (answer + (long)dp[n][j] * combination(K, j) % mod * comb[j]) % mod;
        }

        long totalPower = fastPower(K, n);
        answer = (totalPower - answer + mod) % mod;
        System.out.println(answer);
        sc.close();
    }
}
